<!--suppress HtmlUnknownTag, HtmlUnknownAttribute, CheckEmptyScriptTag -->
<template>
  <v-container>
    <div class="grid-masonry">
      <v-card outlined>
        <v-card-title>Formular de contact</v-card-title>
        <v-card-text>
          <p>
            Formularul de față este o mai bună cale de-a mă contacta decât rețelele sociale, unde conturile-mi sunt abandonate sau inexistente. Nu e mesagerie în direct, deci includeți și o formă de contact (preferabil email) dacă vă așteptați să vă răspund!
          </p>
          <p>
            S-ar putea să nu meargă din când în când din pricina prea strictei protecții anti-spam; caz în care reveniți mai târziu.
            Iar și când merge, s-ar putea să nu primesc mesajul de îndată; o să fie stocat într-o bază de date undeva.
          </p>
        </v-card-text>
      </v-card>
      <v-card outlined>
        <v-card-title>Contact form</v-card-title>
        <v-card-text>
          <p>
            This form is a better way to contact me than social media, where my accounts may be abandoned or
            nonexistent. It's not live chat, so include a contact form of your own (preferably email) if I am to get
            back to you!
          </p>
          <p>
            It may not work at times due to anti-spam overkill; if it's disabled or errors out, refresh the page later.
            And when it does, I may not immediately receive your message; it'll be in a database somewhere.
          </p>
        </v-card-text>
      </v-card>
    </div>
    <span>
      <v-text-field class="ctrl-enter" filled outlined v-model="title" label="T"
                    :disabled="!formElementsEnabled"/>

      <v-textarea class="ctrl-enter" filled outlined v-model="content" label="M"
                  :disabled="!formElementsEnabled"/>

      <v-file-input v-if="uploadVisible || uploadVisibleOverride"
                    small-chips v-model="file" label="Upload file" :disabled="!formElementsEnabled"/>

      <v-btn :disabled="!formElementsEnabled" :loading="restCallsGoing > 0"
             width="inherit" elevation="7" x-large
             @click="submitMessage()">
          S&emsp;<small style="opacity:0.7">(Ctrl+Enter)</small>
      </v-btn>
    </span>

    <Notifications :alerts="alerts" :floating="true"/>
  </v-container>
</template>

<script>
import AxiosHelper from '../components/AxiosHelper.vue';
import Notifications from '../components/Notifications.vue';

export default {
    components: { Notifications },

    mixins: [AxiosHelper],

    props: ['uploadVisible'],

    data: () => ({
      formEnabled: false,
      uploadVisibleOverride: false,

      title: '',
      content: '',
      file: null
    }),

    computed: {
      formElementsEnabled () {
        return this.formEnabled && !this.restCallsGoing;
      }
    },

    watch: {
      content () {
        if (this.content === 'upload')
          this.uploadVisibleOverride = true;
      }
    },

    methods: {
      submitMessage () {
        let formData = new FormData();
        formData.append('title', this.title);
        formData.append('content', this.content);
        formData.append('receivedFrom', location.host);
        if (this.file)
          formData.append('file', this.file, this.file.name);

        this.credentialedAxios('submitting form', axios => axios.post(this.$apiUrl + '/contact', formData), this.onSubmitSuccessful)
          .then(() => this.checkEnabled());
      },

      onSubmitSuccessful() {
        this.alerts.push({type: 'info', text: 'Got it!'});
        this.title = '';
        this.content = '';
        this.file = null;
      },

      checkEnabled() {
        this.credentialedAxios('checking whether the form is enabled', axios => axios.get(this.$apiUrl + '/contact/enabled'),
          data => this.formEnabled = data);
      }
    },

    mounted () {
      this.checkEnabled();

      document.querySelectorAll('.ctrl-enter input, .ctrl-enter textarea')
        .forEach(fld => fld.onkeydown = key => {
          if (key.keyCode === 13 && key.ctrlKey)
            this.submitMessage()
      });
    }
  }
</script>

